from content_common import *

def build(b, N):
    b.h1(1, "บทนำ")
    b.h2("1.1 ความสำคัญและที่มาของปัญหา")
    b.p(ot(113, {"[1]": "{c:nxpo2021,ltleds2022}"}))
    b.p(ot(114, {"[2]": "{c:tripathi2019}", "[3, 4]": "{c:windeatt2014}", "[5]": "{c:wangf2021}", "140x109 (กิกะ)ตันต่อปี": "140 × 10<sup>9</sup> ตันต่อปี"}))
    b.p(ot(115, {"[6]": "{c:akinyemi2020}", "Zhang, Y., (2022) [7]": "Zhang และคณะ (2022) {c:zhang2022}", "ดังแสดงในภาพที่ 1-1": "ดังแสดงใน{fig:cycle}"}))
    b.fig("cycle", fp("s_biochar_cycle"), 13.0, "วงจรเศรษฐกิจหมุนเวียนของชีวมวลเหลือทิ้ง ถ่านชีวภาพ และวัสดุก่อสร้าง (ผู้วิจัยวาดใหม่ตามแนวคิดของ {c:zhang2022})")
    b.p(ot(118, {"[9, 10]": "{c:he2022,maljaee2021}", "[10-12]": "{c:maljaee2021,chen2022,sajjadi2019}", "ดังแสดงในภาพที่ 1-2": "ดังแสดงใน{fig:pyro}"}))
    b.fig("pyro", fp("s_pyrolysis"), 13.0, "เส้นทางการผลิตถ่านชีวภาพจากชีวมวลด้วยไพโรไลซิส แก๊สซิฟิเคชัน และคาร์บอไนเซชันด้วยไฮโดรเทอร์มัล (ผู้วิจัยวาดใหม่ตาม {c:zhang2022})")
    b.p(ot(121, {"การดูดซึมน้ำ ตามมาตรฐาน มอก.827-2565": "การดูดซึมน้ำ ตามมาตรฐาน มอก.827-2565 รวมถึงความต้านทานการลื่นไถล"}))
    b.p(ot(122, {"[13, 14]": "{c:andrew2019,habert2020}", "ดังแสดงในภาพที่ 1-3 และภาพที่ 1-4": "ดังแสดงใน{fig:tgo1}และ{fig:tgo2}", "[15, 16]": "{c:scrivener2018,habert2020}", "[17]": "{c:barbhuiya2024}"}))
    b.p(f"ในระดับโลก Andrew (2019) {{c:andrew2019}} รายงานว่าการผลิตซีเมนต์ปล่อย CO<sub>2</sub> จากกระบวนการ (process emission) ราว 1.50 ± 0.12 Gt ในปี ค.ศ. 2018 หรือประมาณร้อยละ 4 ของการปล่อยจากเชื้อเพลิงฟอสซิล ส่วน Habert และคณะ (2020) {{c:habert2020}} ประเมินว่าการดำเนินมาตรการลดคาร์บอนตลอดห่วงโซ่คุณค่าของซีเมนต์และคอนกรีตร่วมกันสามารถลดการปล่อยก๊าซเรือนกระจกได้สูงสุดราวร้อยละ 50 สำหรับประเทศไทย Khongprom และ Suwanmanee (2017) {{c:khongprom2017}} รายงานว่าซีเมนต์ปอร์ตแลนด์ทั่วไปมีค่า GWP ประมาณ 0.76 ตัน CO<sub>2</sub>e ต่อตันซีเมนต์ และการเผาไหม้เชื้อเพลิงฟอสซิลร่วมกับการแคลไซน์รวมกันคิดเป็นกว่าร้อยละ 91 ของ GWP ดังกล่าว ตัวเลขเหล่านี้ทำให้การลดปริมาณซีเมนต์ต่อหน่วยคอนกรีตเป็นมาตรการที่ให้ผลโดยตรงที่สุด")
    b.fig("tgo1", op("tgo1"), 12.0, "ผลการพยากรณ์ปริมาณการปล่อยก๊าซ CO<sub>2</sub> ในช่วงปี ค.ศ. 2006–2020", source="ที่มา: ศูนย์ข้อมูลก๊าซเรือนกระจก องค์การบริหารจัดการก๊าซเรือนกระจก, Greenhouse Gas Mitigation Potential of Cement Industry in Thailand")
    b.fig("tgo2", op("tgo2"), 12.0, "กราฟแสดงแนวโน้มการปล่อยก๊าซเรือนกระจกภาค IPPU ปี พ.ศ. 2543–2556", source="ที่มา: ศูนย์ข้อมูลก๊าซเรือนกระจก องค์การบริหารจัดการก๊าซเรือนกระจก, Greenhouse Gas Emissions from Industrial Process and Product Use Sector")
    b.p(ot(129).replace("ถ่านชีวภาพจากไม้ไผ่เพื่อทดแทนวัสดุหลักในการผสมคอนกรีต เช่น ทรายและหินธรรมชาติ", "ถ่านชีวภาพจากไม้ไผ่เพื่อทดแทนวัสดุหลักในการผสมคอนกรีต ได้แก่ ซีเมนต์ (ด้วยไบโอชาร์) และทราย (ด้วยเศษคอนกรีต)"))

    b.h2("1.2 ช่องว่างงานวิจัยและความแปลกใหม่ของงานนี้")
    b.p("งานวิจัยเรื่องไบโอชาร์ในวัสดุซีเมนต์ส่วนใหญ่ใช้มอร์ตาร์หรือคอนกรีตเป็นตัวอย่างทดสอบ และพบผลที่แตกต่างกันตามปริมาณที่ใช้ Wang และคณะ (2020) {c:wang2020} รายงานว่าไบโอชาร์ร้อยละ 1 โดยน้ำหนักเพิ่มกำลังอัดของวัสดุซีเมนต์ที่บ่มด้วย CO<sub>2</sub> ร้อยละ 8.9 แต่ที่ร้อยละ 5 กำลังอัดลดลง Legan และคณะ (2025) {c:legan2025} พบว่าในมอร์ตาร์ที่ใช้ไบโอชาร์จากเศษไม้แทนซีเมนต์ร้อยละ 5 10 และ 15 มีเพียงสูตรร้อยละ 5 ที่มีกำลังอัดสูงกว่าสูตรควบคุม (สูงกว่าร้อยละ 4 ที่ 7 วัน และร้อยละ 6 ที่ 28 วัน) ขณะที่ Hylton และคณะ (2024) {c:hylton2024} ระบุว่ามีรายงานจำนวนมากพบกำลังลดลงเมื่อทดแทนซีเมนต์เกินร้อยละ 5 แต่ไบโอชาร์บางชนิดสามารถทดแทนได้ร้อยละ 10 โดยไม่ทำให้กำลังอัดสูงสุดลดลง สำหรับไบโอชาร์จากไม้ไผ่ Chin และคณะ (2025) {c:chin2025} พบว่าปริมาณร้อยละ 6 ให้กำลังอัดสูงสุด 46.98 MPa ในมอร์ตาร์ที่ w/c 0.45")
    b.p("ในด้านบล็อกปูพื้น มีงานที่ใช้ RCA และวัสดุเหลือทิ้งอื่นหลายชนิด เช่น Wang และคณะ (2019) {c:wangx2019} เสนอระดับการทดแทนมวลรวมหยาบรีไซเคิลร้อยละ 60 และมวลรวมละเอียดรีไซเคิลร้อยละ 20 Contreras Llanes และคณะ (2022) {c:contreras2022} รายงานว่าใช้มวลรวมรีไซเคิลได้ถึงร้อยละ 50 โดยการดูดซึมน้ำต่ำกว่าร้อยละ 6.0 และกำลังดึงมากกว่า 3.6 MPa ส่วน Rodríguez และคณะ (2017) {c:rodriguez2017} ทดสอบบล็อกที่ใช้มวลรวมรีไซเคิลร้อยละ 15 และ 30 ในระดับอุตสาหกรรมและตรวจสอบความต้านทานการลื่นไถลด้วย อย่างไรก็ตาม จากงานที่ตรวจพบในการทบทวนครั้งนี้ ซึ่งไม่ได้ครอบคลุมทุกฐานข้อมูล ยังไม่พบรายงานที่ศึกษาไบโอชาร์ไม้ไผ่ร่วมกับ RCA จากห้องปฏิบัติการในบล็อกปูพื้นเดียวกัน พร้อมกับความต้านทานการลื่นไถลและการประเมินวัฏจักรชีวิต")
    b.p("ส่วนการประเมินวัฏจักรชีวิต Soares และคณะ (2025) {c:soares2025} ทบทวนเชิงระบบงาน LCA ของบล็อกปูพื้น 45 เรื่อง ส่วน Pizoń และคณะ (2026) {c:pizon2026} แสดงว่าซีเมนต์เป็นตัวขับ GWP หลักของคอนกรีตที่ใช้มวลรวมจากบล็อกปูพื้นบดและตัวลดแรงลดน้ำปริมาณสูงอาจหักล้างประโยชน์ที่ได้จากการแทนมวลรวม ข้อสังเกตนี้ชี้ว่าการประเมินวัสดุทดแทนต้องพิจารณาผลกระทบทางอ้อมของส่วนผสมอื่นควบคู่กัน งานวิจัยนี้จึงเพิ่มการทดสอบความต้านทานการลื่นไถลและการประเมินคาร์บอนเบื้องต้นเข้ากับการทดสอบสมบัติกลและกายภาพตามมาตรฐาน เพื่อให้ได้ภาพรวมสมรรถนะของบล็อกปูพื้นสูตรใหม่ในมิติเดียวกัน")

    b.h2("1.3 วัตถุประสงค์")
    b.plain(ot(131, {"1.2.1": "1.3.1"}), after=60, first=False, left=907, hanging=567)
    b.plain(ot(132, {"1.2.2": "1.3.2"}), after=60, first=False, left=907, hanging=567)
    b.plain(ot(133, {"1.2.3": "1.3.3"}), after=60, first=False, left=907, hanging=567)
    b.plain("1.3.4 เพื่อประเมินคาร์บอนฟุตพรินต์เบื้องต้นแบบ cradle-to-gate ของแต่ละสูตรผสม และประสิทธิภาพเชิงคาร์บอนเทียบกับกำลังอัด (carbon intensity, ci)", after=60, first=False, left=907, hanging=567)
    b.plain("1.3.5 เพื่อเปรียบเทียบผลการทดสอบกับเกณฑ์มาตรฐานในประเทศและต่างประเทศ ผลิตภัณฑ์ในท้องตลาด และงานวิจัยอื่นที่ตรวจสอบแล้ว", after=120, first=False, left=907, hanging=567)

    b.h2("1.4 ขอบเขตการวิจัย")
    b.p("การทดลองแบ่งเป็น 2 ชุด ชุดที่ 1 ใช้เศษคอนกรีตรีไซเคิล (RCA) แทนมวลรวมละเอียดร้อยละ 50 คงที่ และใช้ถ่านชีวภาพจากไม้ไผ่ทดแทนซีเมนต์ โดยออกแบบอัตราทดแทนไว้ร้อยละ 5 10 15 20 และ 25 ของมวลซีเมนต์สูตรควบคุม ทั้งนี้ ณ วันที่จัดทำรายงานนี้ มีผลทดสอบครอบคลุมอัตราร้อยละ 0 ถึง 15 สำหรับร้อยละ 20 และ 25 อยู่ระหว่างดำเนินการ ชุดที่ 2 ใช้ไบโอชาร์ 48 กรัมต่อก้อนคงที่ และใช้ RCA แทนทรายร้อยละ 0 5 10 และ 15 โดยมวล")
    b.p(ot(135).replace("สูตรส่วนผสม “การพัฒนานวัตกรรมคอนกรีตบล็อกปูพื้นทางจากเศษคอนกรีตเหลือทิ้งและถ่านชีวภาพจากไม้ไผ่ ตามแนวทางเป้าหมายการพัฒนาที่ยั่งยืน” โดยมีรายละเอียดของวัสดุและขอบเขตการทดสอบ ประกอบด้วยการใช้", "วัสดุที่ใช้ประกอบด้วย").replace("ทดแทนซีเมนต์ในอัตราส่วนประมาณร้อยละ 5 10 15 และ 20 และ ใช้", "(ใช้ทดแทนซีเมนต์) และใช้").replace("ทดแทนทรายในอัตราร้อยละ 5 10 และ 15 ในส่วนของมวลรวมละเอียด", "(ใช้ทดแทนทราย) ส่วนมวลรวมละเอียด"))
    b.p("การทดสอบดำเนินการที่อายุบ่ม 7 14 และ 28 วัน ครอบคลุมความหนาแน่น กำลังต้านทานแรงอัด การดูดซึมน้ำที่ 72 ชั่วโมง และความต้านทานการลื่นไถลด้วย British Pendulum Tester (BPT) ทั้งสภาวะแห้งและเปียก ทุกอัตราส่วนผสมขึ้นรูป 3 ก้อนต่ออายุบ่ม นอกจากนี้ได้เปรียบเทียบกำลังอัดกับผลิตภัณฑ์ท้องตลาด 2 แหล่งและกับชิ้นทดสอบทรงลูกบาศก์ และประเมิน GWP แบบ cradle-to-gate ต่อบล็อก 1 ลูกบาศก์เมตร โดยไม่รวมการขนส่ง พลังงานในโรงงาน การใช้งาน และการจัดการเมื่อสิ้นอายุ")
    b.p("<b>หมายเหตุเกี่ยวกับสถานะข้อมูล:</b> ผลการทดสอบความหนาแน่น กำลังอัด และการดูดซึมน้ำในรายงานนี้เป็นข้อมูลที่บันทึกจากการทดลองและนำเสนอตามต้นฉบับ ส่วนผลความต้านทานการลื่นไถลที่ปรากฏในบทที่ 4 เป็นค่าสมมติ " + PH + " เพื่อแสดงกรอบการวิเคราะห์ ซึ่งต้องแทนที่ด้วยค่าที่วัดจริงก่อนเผยแพร่ ส่วนค่าสัมประสิทธิ์การปล่อยในการประเมินคาร์บอนเป็นค่าสมมติฐานระดับคัดกรองที่ต้องแทนที่ด้วยข้อมูลบัญชีรายการของไทยหรือฐานข้อมูลสากล")

    b.h2("1.5 สมมติฐานการวิจัย")
    b.p("สมมติฐานตั้งบนกลไกทางวัสดุศาสตร์ที่อภิปรายในบทที่ 2 และสรุปไว้ใน{fig:hyp} ดังนี้ H1 การลดซีเมนต์และเพิ่มอนุภาคพรุนของไบโอชาร์ทำให้ความหนาแน่นและกำลังอัดลดลงตามอัตราทดแทน H2 ภายใต้ปริมาณไบโอชาร์คงที่ RCA ที่มีผิวเหลี่ยมมุมและมีมอร์ตาร์เดิมเกาะผิวทำให้กำลังอัดเพิ่มขึ้นตามอัตราทดแทนในช่วงที่ศึกษา H3 ค่า BPN สภาวะเปียกต่ำกว่าสภาวะแห้ง และลดลงเมื่อไบโอชาร์เพิ่ม H4 GWP ต่อลูกบาศก์เมตรลดลงตามปริมาณซีเมนต์ที่ลดลง H5 ประสิทธิภาพเชิงคาร์บอนต่อ MPa ขึ้นอยู่กับว่ากำลังอัดที่สูญเสียมากกว่าซีเมนต์ที่ลดลงหรือไม่")
    b.fig("hyp", fp("s_hypotheses"), 14.0, "กรอบสมมติฐานและกลไกที่คาดว่าเกิดขึ้นระหว่างตัวแปรต้น กลไกทางวัสดุ และผลลัพธ์ที่วัด")

    b.h2("1.6 ประโยชน์ที่คาดว่าจะได้รับ")
    b.plain(ot(137, {"1.4.1": "1.6.1"}), after=60, first=False, left=907, hanging=567)
    b.plain(ot(138, {"1.4.2": "1.6.2"}), after=60, first=False, left=907, hanging=567)
    b.plain(ot(139, {"1.4.3": "1.6.3"}), after=60, first=False, left=907, hanging=567)
    b.plain("1.6.4 ได้ข้อมูลเชิงปริมาณเกี่ยวกับสมดุลระหว่างกำลังอัดและซีเมนต์ที่ลดลง รวมถึงราคาไบโอชาร์ที่คุ้มค่า ซึ่งใช้ตัดสินใจเมื่อจะขยายผลสู่วิสาหกิจชุมชน", after=120, first=False, left=907, hanging=567)

    b.h2("1.7 กรอบแนวคิดและโครงสร้างของรายงาน")
    b.p("กรอบแนวคิดของงานวิจัยแสดงใน{fig:framework} วัสดุเหลือทิ้งสองประเภทถูกแปรรูปเป็นไบโอชาร์และ RCA เพื่อทดแทนซีเมนต์และทรายในบล็อกปูพื้น จากนั้นประเมินผลใน 4 มิติ ได้แก่ สมบัติกล สมบัติกายภาพ ความปลอดภัยในการใช้งาน (ความต้านทานการลื่นไถล) และสิ่งแวดล้อม (LCA) โดยเชื่อมโยงกับเป้าหมายการพัฒนาที่ยั่งยืนข้อ 9 12 และ 13 {c:un2015} รายงานแบ่งเป็น 5 บทตาม{fig:roadmap}")
    b.fig("framework", fp("s_framework"), 14.0, "กรอบแนวคิดของงานวิจัยจากวัสดุเหลือทิ้งสู่สมรรถนะของคอนกรีตบล็อกปูพื้น")
    b.fig("roadmap", fp("s_roadmap"), 14.0, "แผนที่โครงสร้างรายงาน")
